DROP TABLE IF EXISTS `aturan_kurikulum`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `aturan_kurikulum` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `angkatan_mulai` int(11) NOT NULL COMMENT 'Tahun angkatan mulai berlaku (inklusif)',
  `angkatan_selesai` int(11) DEFAULT NULL COMMENT 'Tahun angkatan selesai berlaku (inklusif). NULL = tidak terbatas/berlaku seterusnya',
  `kurikulum_id` int(11) NOT NULL,
  `keterangan` varchar(255) DEFAULT NULL,
  `prioritas` int(11) DEFAULT 0 COMMENT 'Semakin tinggi = semakin diprioritaskan',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_angkatan_range` (`angkatan_mulai`,`angkatan_selesai`),
  KEY `kurikulum_id` (`kurikulum_id`),
  CONSTRAINT `aturan_kurikulum_ibfk_1` FOREIGN KEY (`kurikulum_id`) REFERENCES `kurikulum` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

