  UNIQUE KEY `uk_asesmen` (`kelas_id`,`mahasiswa_id`,`sub_cpmk_id`),
  KEY `an_mhs_fk` (`mahasiswa_id`),
  KEY `an_subcpmk_fk` (`sub_cpmk_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
