INSERT INTO `cpl` VALUES (1,1,'CPL01','Lulusan Bertaqwa kepada Tuhan yang Maha Esa dengan menjunjung tinggi nasionalisme, humanisme, entrepreneurship, dan 7 nilai dasar Universitas Anwar Medika (profesional, visioner, quality focus, trust, integrity, moral, exellence) di bidang Sistem Informasi','Sikap',70.00,'ACTIVE'),(2,1,'CPL02','Lulusan mampu menerapkan pemikiran logis, kritis, dan inovatif dalam pengembangan IPTEK berbasis nilai humaniora; menunjukkan kinerja mandiri dan terukur; menghasilkan serta mengkomunikasikan karya ilmiah sesuai kaidah; mengambil keputusan berbasis data; bekerja sama dan bertanggung jawab dalam tim; serta mengelola pembelajaran dan data secara mandiri, sahih, dan aman','Keterampilan Umum',70.00,'ACTIVE'),(3,1,'CPL03','Lulusan mampu memahami metodologi penelitian, pengembangan produk digital, serta perkembangan teknologi dan bisnis, dan mampu menerapkan pemikiran logis, kritis, sistematis, kreatif, dan inovatif dalam mengidentifikasi masalah, menyusun proposal, melakukan penelitian, mengembangkan produk atau jasa berbasis solusi, menganalisis data, serta menyusun dan mengomunikasikan karya ilmiah secara mandiri maupun kolaboratif dengan memanfaatkan teknologi informasi sesuai kaidah akademik','Pengetahuan',70.00,'ACTIVE'),(4,1,'CPL04','Lulusan mampu memahami dan menerapkan kode etik dalam penggunaan informasi dan data pada perancangan, implementasi, dan penggunaan suatu sistem (Aptikom: IS2020)','Pengetahuan',70.00,'ACTIVE'),(5,1,'CPL05','Lulusan mampu memahami, menganalisis, dan menilai konsep dasar dan peran sistem informasi dalam mengelola data dan memberikan rekomendasi pengambilan keputusan pada proses dan sistem organisasi (Aptikom: IS2020)','Pengetahuan',70.00,'ACTIVE'),(6,1,'CPL06','Lulusan mampu memahami dan menggunakan berbagai metodologi pengembangan sistem beserta alat pemodelan sistem dan menganalisa kebutuhan pengguna dalam membangun sistem informasi untuk mencapai tujuan organisasi (Aptikom: IS2020)','Keterampilan Khusus',70.00,'ACTIVE'),(7,2,'CPL01','Lulusan Bertaqwa kepada Tuhan yang Maha Esa dengan menjunjung tinggi nasionalisme, humanisme, entrepreneurship, dan 7 nilai dasar Universitas Anwar Medika','Sikap & Pengetahuan',70.00,'ACTIVE'),(8,2,'CPL02','Lulusan Mampu menguasai konsep teoritis, mengaplikasikan bidang keahlianya dan mengambil keputusan untuk menyelesaikan permasalahan secara mandiri dan kelompok dengan mengedepankan penguasaan IPTEK, digitalisasi, wawasan kesehatan, dan wawasan kewirausahaan, serta berdaya saing Nasional dan Internasional','Keterampilan Umum',70.00,'ACTIVE'),(9,2,'CPL03','Mampu memahami, menganalisis, dan menilai konsep dasar dan peran sistem informasi dalam mengelola data dan memberikan rekomendasi pengambilan keputusan pada proses dan sistem organisasi. C2,C3,C4','Keterampilan Khusus',70.00,'ACTIVE'),(10,2,'CPL04','Mampu merancang dan menggunakan database, serta mengolah dan menganalisa data dengan alat dan teknik pengolahan data. C5,C3','Keterampilan Khusus',70.00,'ACTIVE'),(11,2,'CPL05','Mampu memahami dan menggunakan berbagai metodologi pengembangan sistem beserta alat pemodelan sistem dan menganalisa kebutuhan pengguna dalam membangun sistem informasi untuk mencapai tujuan organisasi. C2,C3','Keterampilan Khusus',70.00,'ACTIVE'),(12,2,'CPL06','Mampu memahami infrastruktur TI, menganalisis konsep identifikasi, otentikasi, otorisasi akses dalam konteks melindungi orang dan perangkat. C2, C4','Keterampilan Khusus',70.00,'ACTIVE'),(13,2,'CPL07','Mampu memahami dan menerapkan kode etik dalam penggunaan informasi dan data pada perancangan, implementasi, dan penggunaan suatu sistem. C2,C3','Sikap & Etika',70.00,'ACTIVE'),(14,2,'CPL08','Memiliki kemampuan merencanakan, menerapkan, memelihara dan meningkatkan sistem informasi organisasi untuk mencapai tujuan dan sasaran organisasi yang strategis baik jangka pendek maupun jangka panjang. C3, C5','Keterampilan Khusus',70.00,'ACTIVE'),(15,2,'CPL09','Mampu merancang, menerapkan, menjalankan manajemen proyek sistem informasi berbasis smart system, Healthcare dan E-Medical Record. C3','Keterampilan Khusus',70.00,'ACTIVE'),(16,1,'CPL07','Lulusan mampu menganalisis, merancang, mengimplementasikan, dan mengevaluasi solusi Health Informatics System yang mendukung transformasi digital, pengelolaan informasi, dan peningkatan kualitas layanan kesehatan','Keterampilan Khusus',70.00,'ACTIVE'),(17,1,'CPL08','Lulusan mampu mengelola, menganalisis, dan memanfaatkan data serta teknologi cerdas yang mendukung pengambilan keputusan organisasi, khususnya pada sektor kesehatan','Keterampilan Khusus',70.00,'ACTIVE'),(18,1,'CPL09','Lulusan mampu mengembangkan produk, layanan, dan solusi digital, serta mengelola usaha mandiri melalui pemanfaatan teknologi informasi untuk menjawab kebutuhan organisasi dan masyarakat','Keterampilan Khusus',70.00,'ACTIVE'),(19,3,'CPL-03','Menerapkan pemikiran logis, kritis, sistematis, dan inovatif dalam pengembangan atau implementasi ilmu pengetahuan dan teknologi yang dapat berkerjasama dengan lingkungan sekitar, bertoleransi dan memiliki kepedulian terhadap terhadap lingkungan serta mampu mengkaji kasus penerapan ilmu pengetahuan dan teknologi dengan pandangan yang kritis','Keterampilan Umum',70.00,'ACTIVE'),(20,4,'CPL-05','Mampu menganalisis kebutuhan, memodelkan, merancang, mengimplementasikan, dan mengelola artefak rekayasa perangkat lunak menggunakan metode, teknik, dan perangkat pendukung sesuai prinsip Software Engineering.','Keterampilan Umum',70.00,'ACTIVE'),(21,4,'CPL-09','Mampu menerapkan prinsip, metode, standar, dan perangkat pendukung untuk menjamin kualitas, keamanan, serta keandalan perangkat lunak melalui pengujian, software quality assurance, keamanan siber, dan forensik digital sesuai kebutuhan organisasi dan perkembangan teknologi.','Keterampilan Khusus',70.00,'ACTIVE');
/*!40000 ALTER TABLE `cpl` ENABLE KEYS */;
UNLOCK TABLES;

