INSERT INTO `profil_lulusan` VALUES (1,1,'PL01','Eksekutif Profesional (kekhasan universitas)','Lulusan mampu bekerja secara profesional, beretika, berkomunikasi efektif, berkolaborasi multidisiplin, serta memimpin pengembangan solusi digital sesuai kebutuhan.\nProfesi: Eksekutif Profesional (kekhasan universitas)'),(2,1,'PL02','System Analyst, IT Auditor, Data Analyst','Lulusan memiliki kemampuan menganalisis, merancang, membuat, mengaudit, dan melakukan evaluasi sistem informasi yang selaras dengan tujuan organisasi.\nProfesi: System Analyst, IT Auditor, IT Governance, Data Analyst (Aptikom: IS2020)'),(3,1,'PL03','IT Consultant and Developer, Project Manager','Lulusan memiliki kemampuan memahami, menerapkan dan mengintegrasikan model sistem, menggunakan metode dan berbagai teknik peningkatan bisnis proses yang mendatangkan suatu nilai untuk organisasi.\nProfesi: IT Consultant and Developer, Project Manager, Computer Support (Aptikom: IS2020)'),(4,1,'PL04','Health Informatics Specialist (kekhasan prodi)','Lulusan memiliki kemampuan mengembangkan dan menerapkan solusi Health Informatics berbasis teknologi cerdas untuk mendukung transformasi digital, pengelolaan data, dan peningkatan kualitas layanan kesehatan.\nProfesi: Health Informatics Specialist (kekhasan prodi)'),(5,1,'PL05','Technopreneur (kekhasan prodi)','Lulusan memiliki kemampuan mengidentifikasi peluang, merancang, mengembangkan, dan mengelola produk atau layanan digital yang inovatif dan bernilai bisnis dengan menjunjung etika profesi, karakter humanis, dan tanggung jawab sosial.\nProfesi: Technopreneur (kekhasan prodi)'),(6,2,'PL01','Profil Lulusan PL01','Lulusan Bertaqwa kepada Tuhan yang Maha Esa dengan menjunjung tinggi nasionalisme, humanisme, entrepreneurship, dan 7 nilai dasar Universitas Anwar Medika mencakup S'),(7,2,'PL02','Profil Lulusan PL02','Lulusan Mampu menguasai konsep teoritis, mengaplikasikan bidang keahliannya dan mengambil keputusan untuk menyelesaikan permasalahan secara mandiri dan kelompok dengan mengedepankan penguasaan IPTEK, digitalisasi, wawasan kesehatan, dan wawasan kewirausahaan, serta berdaya saing Nasional dan Internasional mencakup KU'),(8,2,'PL03','Profil Lulusan PL03','Lulusan memiliki kemampuan menganalisis, merancang, membuat, dan melakukan evaluasi sistem informasi yang selaras dengan tujuan organisasi. (IS2020) mencakup KK'),(9,2,'PL04','Profil Lulusan PL04','Lulusan memiliki kemampuan memahami, menerapkan dan mengintegrasikan\nmodel sistem, menggunakan metode dan berbagai teknik peningkatan bisnis\nproses yang mendatangkan suatu nilai untuk organisasi. (IS2020) mencakup KK'),(10,2,'PL05','Profil Lulusan PL05','Lulusan memiliki kemampuan merencanakan, membangun, menerapkan, dan mengoperasikan sistem informasi berorientasi Smart System, Healthcare dan E-Medical Record mencakup P, KK');
/*!40000 ALTER TABLE `profil_lulusan` ENABLE KEYS */;
UNLOCK TABLES;

