DROP TABLE IF EXISTS `rpl_mahasiswa`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `rpl_mahasiswa` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `mahasiswa_id` int(11) NOT NULL,
  `kurikulum_id` int(11) NOT NULL,
  `skema_semester` tinyint(4) DEFAULT NULL,
  `status` enum('AKTIF','SELESAI','NONAKTIF') NOT NULL DEFAULT 'AKTIF',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_rpl_mahasiswa` (`mahasiswa_id`),
  KEY `idx_rpl_kurikulum` (`kurikulum_id`),
  CONSTRAINT `fk_rpl_mhs_kurikulum` FOREIGN KEY (`kurikulum_id`) REFERENCES `kurikulum` (`id`),
  CONSTRAINT `fk_rpl_mhs_user` FOREIGN KEY (`mahasiswa_id`) REFERENCES `users` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
