              \"skala\": {\n                    \"1\": \"Tingkat kehadiran rendah, sering melanggar tata tertib.\",\n                    \"2\": \"Sering terlambat hadir dan mengabaikan jadwal yang disepakati.\",\n                    \"3\": \"Hadir tepat waktu namun terkadang terlambat pada pengumpulan progres.\",\n                    \"4\": \"Disiplin hadir tepat waktu dan menaati batas waktu pengumpulan tugas.\",\n                    \"5\": \"Selalu hadir tepat waktu, siap materi, mengumpulkan selalu sebelum deadline.\"\n                }\n            }\n        ]\n    },\n    \"portofolio\": {\n        \"aktif\": true,\n        \"judul\": \"Rubrik Penilaian Portofolio Mahasiswa (Kumpulan Artefak Proyek SI)\",\n        \"artefak\": [\n            {\n                \"no\": \"1\",\n                \"nama\": \"Laporan Analisis Lingkungan Bisnis & SI\",\n                \"sub_cpmk\": \"Sub-CPMK 01 & 02\",\n                \"bobot\": \"20\",\n                \"kriteria\": \"Ketajaman analisis SWOT\\/Value Chain, keselarasan gap kebutuhan SI, validitas data observasi organisasi.\",\n                \"bukti\": \"Dokumen Laporan Bab 1-2 + Lembar Kerja Analisis Kasus\",\n                \"minggu\": \"Minggu Ke-4\"\n            },\n            {\n                \"no\": \"2\",\n                \"nama\": \"Blueprint Arsitektur Sistem Informasi\",\n                \"sub_cpmk\": \"Sub-CPMK 03 & 04\",\n                \"bobot\": \"30\",\n                \"kriteria\": \"Kelengkapan domain TOGAF (Arsitektur Bisnis, Data, Aplikasi, Teknologi), ketepatan diagram modeling dan katalog aplikasi.\",\n                \"bukti\": \"Dokumen Blueprint SI + Diagram Arsitektur (UML\\/ArchiMate)\",\n                \"minggu\": \"Minggu Ke-8 (UTS)\"\n            },\n            {\n                \"no\": \"3\",\n                \"nama\": \"Roadmap Implementasi & Risk Register\",\n                \"sub_cpmk\": \"Sub-CPMK 05 & 06\",\n                \"bobot\": \"25\",\n                \"kriteria\